import java.lang.reflect.*;

// 没有实现任何接口的类
class Plain { public String who() { return "plain object"; } }
interface IPlain { String who(); }
class PlainImpl implements IPlain { public String who() { return "plain impl"; } }
public class Main {
    public static void main(String[] a) {
        // JDK 动态代理【必须】基于接口；传一个 class（非接口）会抛 IllegalArgumentException
        try {
            Proxy.newProxyInstance(Plain.class.getClassLoader(),
                new Class[]{Plain.class},
                new InvocationHandler() {
                    public Object invoke(Object p, Method m, Object[] args) throws Throwable {
                        return m.invoke(new Plain(), args);
                    }
                });
            System.out.println("JDK proxy on class: allowed (unexpected)");
        } catch (IllegalArgumentException e) {
            System.out.println("JDK proxy needs interface: " + e.getMessage());
        }
        // 有接口时 JDK 代理正常工作
        IPlain p = (IPlain) Proxy.newProxyInstance(IPlain.class.getClassLoader(),
            new Class[]{IPlain.class},
            new InvocationHandler() {
                public Object invoke(Object pr, Method m, Object[] args) throws Throwable {
                    System.out.println("[jdk before]");
                    return m.invoke(new PlainImpl(), args);
                }
            });
        System.out.println(p.who());
    }
}
